require_once __DIR__.'/../config/config.php';
require_once __DIR__.'/../config/config.php';
<?php
requireRole(['Administrator','Editor','Viewer']);require_once __DIR__.'/../app/layout.php';$pdo=db();$year=(int)($_GET['year']??date('Y'));$byArea=$pdo->prepare('SELECT a.name area,COUNT(*) lines,SUM(p.quantity) qty,SUM(p.quantity*p.unit_price) abc FROM ppmp_items p JOIN areas a ON a.id=p.area_id WHERE p.fiscal_year=? GROUP BY a.id ORDER BY abc DESC');$byArea->execute([$year]);$rows=$byArea->fetchAll();$pr=$pdo->prepare('SELECT status,COUNT(*) total FROM purchase_requests WHERE fiscal_year=? GROUP BY status');$pr->execute([$year]);$prRows=$pr->fetchAll();$po=$pdo->prepare('SELECT o.status,COUNT(*) total FROM purchase_orders o JOIN purchase_requests r ON r.id=o.pr_id WHERE r.fiscal_year=? GROUP BY o.status');$po->execute([$year]);$poRows=$po->fetchAll();pageStart('Procurement Reports');?><div class="grid"><div class="panel"><h2>PPMP Summary by Area/Unit — FY <?=$year?></h2><div class="table-wrap"><table class="table"><tr><th>Area/Unit</th><th>PPMP Lines</th><th>Quantity</th><th>Total ABC</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['area'])?></td><td><?=number_format($r['lines'])?></td><td><?=number_format($r['qty'],2)?></td><td>₱<?=number_format($r['abc'],2)?></td></tr><?php endforeach;?></table></div></div><div class="panel"><h2>Workflow Status</h2><h3>Purchase Requests</h3><?php foreach($prRows as $r):?><p><span class="badge"><?=e($r['status'])?></span> <?=number_format($r['total'])?></p><?php endforeach;?><h3>Purchase Orders</h3><?php foreach($poRows as $r):?><p><span class="badge"><?=e($r['status'])?></span> <?=number_format($r['total'])?></p><?php endforeach;?></div></div><?php pageEnd();